function storedObjectCount(contents) {
  const store = new Map();
  for (const content of contents) {
    writeObject(store, content);
  }
  return store.size;
}

function gitStorageKB(numCommits, projectSizeKB, changedFraction) {
  if (numCommits <= 0) return 0;
  const firstCommit = projectSizeKB;
  const laterCommits = (numCommits - 1) * projectSizeKB * changedFraction;
  return firstCommit + laterCommits;
}

