items.solution:
function storageSavingsPercent(numCommits, projectSizeKB, changedFraction) {
  const manualCopyKB = numCommits * projectSizeKB;
  const gitKB = projectSizeKB + (numCommits - 1) * projectSizeKB * changedFraction;
  return Math.round(100 * (1 - gitKB / manualCopyKB));
}

